const pageMfa = `-- name: PageMfa :many

SELECT u.id, u.name, u.username,
       m.id_core_users AS mfa_user_id, m.user_name AS mfa_user_name,
       m.method, m.confirmed_at, m.enabled, m.last_used_at,
       m.recovery_codes_left
FROM core_users u
LEFT JOIN core_user_mfa m ON m.id_core_users = u.id
WHERE ($1::text IS NULL OR (
          u.name ILIKE '%' || $1::text || '%'
       OR u.username ILIKE '%' || $1::text || '%'
       OR m.user_name ILIKE '%' || $1::text || '%'))
ORDER BY
  CASE WHEN $2::text = 'user_name:asc' THEN u.name END ASC,
  CASE WHEN $2::text = 'user_name:desc' THEN u.name END DESC,
  CASE WHEN $2::text = 'username:asc' THEN u.username END ASC,
  CASE WHEN $2::text = 'username:desc' THEN u.username END DESC,
  u.id ASC
LIMIT $4
OFFSET $3
`

